export const GLOSSARY_SHARD = Object.freeze({"bitcoin":{"slug":"bitcoin","cat":"basics","en":"Bitcoin (BTC)","contentLocale":"id","term":"Bitcoin (BTC)","aka":["BTC","bitcoin"],"short":"Bitcoin (BTC) adalah aset kripto pertama yang diluncurkan pada 2009, berjalan di jaringan terdesentralisasi dengan proof of work dan jumlah maksimal 21 juta koin.","body":[["Bitcoin dirancang oleh sosok anonim bernama ",["Satoshi","satoshi"]," Nakamoto sebagai uang elektronik antar pengguna tanpa perantara. Transaksi diverifikasi oleh penambang (miner) yang bersaing memecahkan teka-teki komputasi. Penambang yang berhasil menambahkan blok baru dan menerima imbalan berupa BTC baru serta biaya transaksi."],"Pasokan Bitcoin dibatasi 21 juta koin. Imbalan blok berkurang separuh kira-kira setiap empat tahun lewat peristiwa halving. Halving April 2024 menurunkan imbalan menjadi 3,125 BTC per blok. Satu BTC bisa dipecah menjadi 100.000.000 satoshi, jadi Anda tidak perlu membeli satu koin utuh.",["Sejak Januari 2024, ETF spot bitcoin diperdagangkan di Amerika Serikat, sehingga investor institusi bisa mendapat eksposur tanpa memegang koinnya langsung. Di exchange, BTC biasanya diperdagangkan dalam pasangan seperti BTC/",["USDT","usdt"]," atau BTC/IDR."]],"example":"Misalkan BTC diperdagangkan di 1.000.000.000 rupiah per koin. Dengan Rp500.000 Anda bisa membeli 0,0005 BTC, atau 50.000 satoshi. Jika harga naik 10% menjadi Rp1.100.000.000, nilai 0,0005 BTC Anda menjadi Rp550.000. Jika harga turun 10%, nilainya menjadi Rp450.000. Angka ini hanya ilustrasi untuk menunjukkan bahwa membeli pecahan kecil tetap bergerak persis mengikuti persentase harga BTC.","mistakes":["Menunda membeli karena mengira harus membeli 1 BTC penuh.","Mengirim BTC ke alamat jaringan lain, misalnya alamat BEP20, tanpa memeriksa jaringan yang didukung penerima.","Mengira Bitcoin anonim sepenuhnya, padahal semua transaksi tercatat publik di blockchain."],"faq":[{"q":"Berapa jumlah maksimal Bitcoin?","a":"Jumlah maksimal Bitcoin adalah 21 juta koin. Koin baru terus ditambang dengan laju yang makin lambat setiap halving hingga batas itu tercapai."},{"q":"Bisakah membeli Bitcoin dengan modal kecil?","a":"Bisa. Satu BTC terdiri dari 100 juta satoshi, sehingga Anda dapat membeli pecahan kecil sesuai batas minimum pembelian di exchange yang Anda pakai."}],"title":"Apa itu Bitcoin (BTC)? Arti dan cara kerjanya","description":"Pahami apa itu Bitcoin, kenapa jumlahnya dibatasi 21 juta, cara kerja penambangan dan halving, serta cara membeli pecahan BTC.","related":[["satoshi","Satoshi (sats)","Satoshi atau sats adalah satuan terkecil Bitcoin, di mana 1 BTC sama dengan 100.000.000 satoshi."],["bitcoin-halving","Bitcoin halving","Bitcoin halving adalah peristiwa terjadwal kira-kira setiap empat tahun, atau tepatnya setiap 210.000 blok, ketika imbalan blok untuk penambang dipotong setengah."],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) adalah mekanisme konsensus di mana penambang bersaing memecahkan teka-teki komputasi agar berhak menambahkan blok baru dan menerima imbalan."],["mining","Mining (penambangan kripto)","Mining atau penambangan kripto adalah proses memakai daya komputasi untuk memvalidasi transaksi dan menambahkan blok baru pada blockchain proof of work, dengan imbalan koin baru dan biaya transaksi."],["spot-bitcoin-etf","ETF Bitcoin spot","ETF Bitcoin spot adalah reksa dana yang diperdagangkan di bursa saham dan memegang bitcoin asli sebagai aset dasarnya, sehingga harga sahamnya mengikuti harga BTC."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Satu bitcoin harganya segitu. Apakah saya masih bisa beli sedikit?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"proof-of-work":{"slug":"proof-of-work","cat":"basics","en":"Proof of work (PoW)","contentLocale":"id","term":"Proof of work (PoW)","aka":["PoW","bukti kerja"],"short":"Proof of work (PoW) adalah mekanisme konsensus di mana penambang bersaing memecahkan teka-teki komputasi agar berhak menambahkan blok baru dan menerima imbalan.","body":[["Dalam PoW, penambang mencoba miliaran angka acak untuk menghasilkan hash blok yang memenuhi target kesulitan tertentu. Mencari jawabannya sulit dan memakan listrik, tetapi memeriksanya sangat mudah. Penambang pertama yang menemukan jawaban menyiarkan bloknya, lalu ",["node","node"]," lain memverifikasi dan menerimanya."],["Biaya energi inilah yang membuat jaringan aman. Untuk menulis ulang riwayat transaksi, penyerang harus menguasai sebagian besar daya hash jaringan, yang sangat mahal pada jaringan besar seperti ",["Bitcoin","bitcoin"],". Tingkat kesulitan disesuaikan berkala agar waktu antarblok tetap stabil, sekitar 10 menit untuk Bitcoin."],["Kritik utama PoW adalah konsumsi listrik yang besar. Bitcoin, Litecoin, dan Dogecoin memakai PoW, sedangkan ",["Ethereum","ethereum"]," meninggalkannya pada September 2022 dan beralih ke ",["proof of stake","proof-of-stake"],"."]],"example":["Misalkan sebuah jaringan PoW memiliki total ",["hash rate","hash-rate"]," 600 EH/s dan Anda menjalankan mesin dengan 0,6 EH/s, atau 0,1% dari jaringan. Jika ada sekitar 144 blok per hari dengan imbalan 3,125 BTC per blok, total imbalan harian sekitar 450 BTC. Secara rata-rata, bagian Anda sekitar 0,1% x 450 = 0,45 BTC per hari, sebelum dikurangi biaya listrik dan biaya pool."],"mistakes":["Mengira PoW berarti siapa pun bisa menambang Bitcoin dengan laptop secara menguntungkan.","Menganggap konfirmasi pertama sudah final untuk transaksi besar, padahal lebih aman menunggu beberapa blok.","Mengira semua blockchain masih memakai PoW, termasuk Ethereum."],"faq":[{"q":"Apa beda proof of work dan proof of stake?","a":"PoW memakai daya komputasi dan listrik untuk mengamankan jaringan. PoS memakai koin yang dikunci validator sebagai jaminan, sehingga konsumsi energinya jauh lebih kecil."},{"q":"Kenapa Bitcoin tetap memakai proof of work?","a":"Komunitas Bitcoin menilai PoW sudah teruji dan sulit dimanipulasi. Mengubah mekanisme konsensus juga butuh kesepakatan luas yang sangat sulit dicapai."}],"title":"Apa itu proof of work (PoW)? Arti dan cara kerja","description":"Arti proof of work, cara penambang mengamankan blockchain dengan daya komputasi, dan bedanya dengan proof of stake.","related":[["mining","Mining (penambangan kripto)","Mining atau penambangan kripto adalah proses memakai daya komputasi untuk memvalidasi transaksi dan menambahkan blok baru pada blockchain proof of work, dengan imbalan koin baru dan biaya transaksi."],["hash-rate","Hash rate","Hash rate adalah total daya komputasi yang dipakai penambang untuk mengamankan blockchain proof of work seperti Bitcoin, diukur dalam jumlah tebakan hash per detik."],["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) adalah mekanisme konsensus di mana validator mengunci koin sebagai jaminan untuk berhak memvalidasi blok, lalu mendapat imbalan atau kena penalti sesuai perilakunya."],["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."],["bitcoin-halving","Bitcoin halving","Bitcoin halving adalah peristiwa terjadwal kira-kira setiap empat tahun, atau tepatnya setiap 210.000 blok, ketika imbalan blok untuk penambang dipotong setengah."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"token-unlock":{"slug":"token-unlock","cat":"basics","en":"Token unlock","contentLocale":"id","term":"Token unlock","aka":["unlock token","pembukaan token","vesting"],"short":"Token unlock adalah saat sejumlah token yang sebelumnya terkunci, misalnya milik tim atau investor awal, dibuka sesuai jadwal vesting sehingga bisa dipindahkan atau dijual.","body":["Banyak proyek mengunci token tim, investor, dan ekosistem agar tidak dijual sekaligus saat peluncuran. Jadwalnya biasanya terdiri dari cliff, yaitu masa tunggu awal tanpa unlock, lalu unlock bertahap bulanan atau harian. Ada juga unlock sekaligus dalam jumlah besar yang sering disebut cliff unlock.",["Unlock menambah ",["circulating supply","circulating-supply"],". Jika penerimanya menjual, tekanan jual bisa meningkat, terutama ketika unlock besar dibanding ",["volume perdagangan","trading-volume"]," harian. Namun tidak semua token yang dibuka langsung dijual, karena sebagian dipakai untuk ",["staking","staking"],", hibah ekosistem, atau disimpan."],["Anda bisa memantau jadwal unlock lewat dokumentasi proyek dan situs pelacak unlock. Bandingkan nilai unlock dengan volume harian dan ",["market cap","market-capitalization"]," untuk menilai seberapa besar dampaknya."]],"example":["Misalkan sebuah token memiliki circulating supply 200 juta dan volume perdagangan harian rata-rata 5 juta ",["USDT","usdt"],". Minggu depan ada unlock 30 juta token untuk investor awal. Pada harga 0,50 USDT, nilai unlock itu 15 juta USDT, atau tiga kali volume harian, dan menambah suplai beredar 15%. Jika sebagian besar dijual, pasar butuh waktu dan permintaan besar untuk menyerapnya."],"mistakes":["Tidak memeriksa kalender unlock sebelum membeli token yang baru diluncurkan.","Menganggap setiap unlock pasti membuat harga turun, padahal reaksi pasar bisa beragam.","Hanya melihat jumlah token yang dibuka tanpa membandingkannya dengan volume dan suplai beredar."],"faq":[{"q":"Apakah token unlock membuat harga turun?","a":"Tidak selalu. Unlock menambah suplai yang bisa dijual, tetapi dampaknya tergantung ukuran unlock, siapa penerimanya, dan kekuatan permintaan pasar."},{"q":"Apa itu cliff dalam vesting?","a":"Cliff adalah masa awal ketika token sama sekali belum bisa dibuka. Setelah cliff berakhir, unlock biasanya berjalan bertahap sesuai jadwal."}],"title":"Apa itu token unlock? Arti dan dampaknya","description":"Arti token unlock dan vesting, cara membaca jadwal cliff, dan cara menilai dampak unlock terhadap suplai dan harga.","related":[["tokenomics","Tokenomics","Tokenomics adalah desain ekonomi sebuah token, mencakup jumlah suplai, cara distribusi, jadwal unlock, kegunaan token, dan mekanisme yang menambah atau mengurangi suplai."],["circulating-supply","Circulating supply (suplai beredar)","Circulating supply adalah jumlah koin atau token yang saat ini benar-benar beredar dan bisa diperdagangkan di pasar, tidak termasuk yang masih terkunci atau belum diterbitkan."],["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) adalah perkiraan nilai sebuah proyek kripto jika seluruh suplai maksimal tokennya sudah beredar, dihitung dari harga saat ini dikali suplai maksimal atau total."],["airdrop","Airdrop","Airdrop adalah pembagian token gratis oleh sebuah proyek kripto ke alamat dompet tertentu, biasanya untuk pengguna awal, pemegang token tertentu, atau sebagai promosi."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"limit-order":{"slug":"limit-order","cat":"trading","en":"Limit order","contentLocale":"id","term":"Limit order","aka":["order limit","pending order"],"short":"Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi.","body":[["Limit order beli hanya dieksekusi di harga limit atau lebih rendah. Limit order jual hanya dieksekusi di harga limit atau lebih tinggi. Jika ",["harga pasar","last-price"]," belum mencapai level Anda, order menunggu di ",["order book","order-book"]," sampai terisi, dibatalkan, atau kedaluwarsa sesuai pengaturan ",["time in force","time-in-force"],"."],["Karena menambah ",["likuiditas","liquidity"]," ke order book, limit order yang menunggu biasanya dikenai biaya maker yang lebih rendah. Namun limit order yang langsung cocok dengan order yang sudah ada tetap dihitung sebagai taker. Gunakan opsi post-only jika ingin memastikan order Anda selalu menjadi maker."],["Limit order juga bisa terisi sebagian. Misalnya Anda memasang beli 1 ",["BTC","bitcoin"],", tetapi hanya 0,4 BTC yang tersedia di harga itu sebelum ",["pasar naik","bull-market"],". Sisanya tetap menunggu di order book."]],"example":"Misalkan ETH diperdagangkan di 3.200 USDT dan Anda ingin membeli lebih murah. Anda memasang limit beli 1 ETH di 3.100 USDT. Dua hari kemudian harga turun ke 3.080 USDT, dan order Anda terisi di 3.100 USDT. Dengan biaya maker 0,08%, biayanya sekitar 2,48 USDT. Jika harga tidak pernah turun ke 3.100, order tidak terisi dan Anda tidak membeli apa pun.","mistakes":["Memasang limit beli di atas harga pasar lalu heran order langsung terisi sebagai taker.","Lupa membatalkan limit order lama yang kemudian terisi saat Anda sudah tidak menginginkannya.","Mengejar harga dengan terus menggeser limit order sehingga tujuannya hilang."],"faq":[{"q":"Kenapa limit order saya tidak terisi?","a":"Harga pasar belum mencapai level limit Anda, atau ada order lain di harga yang sama yang mengantre lebih dulu. Order di harga yang sama dieksekusi berdasarkan urutan waktu."},{"q":"Apakah limit order selalu kena biaya maker?","a":"Tidak. Jika limit order langsung cocok dengan order yang sudah ada di order book, order itu dihitung sebagai taker."}],"title":"Apa itu limit order? Arti dan cara memakainya","description":"Arti limit order di exchange kripto, cara kerjanya di order book, beda biaya maker dan taker, dan kenapa order bisa tidak terisi.","related":[["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin."],["post-only-order","Post-only order","Post-only order adalah limit order yang hanya boleh masuk ke order book sebagai order maker, dan otomatis dibatalkan atau disesuaikan jika akan langsung tereksekusi sebagai taker."],["time-in-force","Time in force (GTC, IOC, FOK)","Time in force adalah pengaturan yang menentukan berapa lama sebuah order tetap aktif dan bagaimana order diperlakukan jika tidak bisa langsung terisi penuh, dengan opsi umum GTC, IOC, dan FOK."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."],["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Pasar, limit, batalkan: apa yang diselesaikan masing-masing?"},"coin":null,"tool":null,"cta":true},"insurance-fund":{"slug":"insurance-fund","cat":"derivatives","en":"Insurance fund","contentLocale":"id","term":"Insurance fund (dana asuransi)","aka":["dana asuransi","dana jaminan likuidasi","insurance fund"],"short":"Insurance fund adalah cadangan dana milik exchange futures yang dipakai untuk menutup kerugian ketika posisi yang dilikuidasi ditutup di harga lebih buruk dari harga kebangkrutannya, sehingga trader lain tidak ikut menanggung.","body":[["Saat ",["posisi dilikuidasi","liquidation"],", mesin likuidasi berusaha menutupnya sebelum margin habis. Jika berhasil ditutup di harga lebih baik dari harga kebangkrutan, sisa margin biasanya masuk ke insurance fund. Jika pasar bergerak terlalu cepat dan posisi ditutup di harga lebih buruk, selisih kerugiannya dibayar dari insurance fund."],["Dana ini berfungsi sebagai penyangga sebelum mekanisme ",["auto-deleveraging","auto-deleveraging"]," dipakai. Semakin besar insurance fund relatif terhadap ",["open interest","open-interest"],", semakin kecil kemungkinan trader yang untung terkena ADL. Banyak exchange besar mempublikasikan saldo insurance fund mereka, dan sebagian memisahkannya per kontrak atau per mata uang margin."],["Insurance fund berbeda dari ",["proof of reserves","proof-of-reserves"],". Insurance fund melindungi sistem dari kerugian likuidasi, bukan menjamin simpanan pengguna jika exchange bangkrut. Cara pengisian, pemakaian, dan transparansinya berbeda tiap exchange."]],"example":["Sebuah posisi long ",["BTC","bitcoin"]," senilai 100.000 ",["USDT","usdt"]," dengan margin 5.000 USDT mencapai level likuidasi. Posisi itu dibuka di 60.000, sekitar 1,67 BTC. Harga kebangkrutannya, yaitu titik di mana margin benar-benar nol, berada di 57.000. Karena pasar jatuh cepat, mesin likuidasi baru bisa menutup posisi di 56.800. Selisih 200 USDT per BTC pada posisi 1,67 BTC berarti kekurangan sekitar 333 USDT, yang dibayar insurance fund. Sebaliknya, jika posisi ditutup di 57.300, sisa sekitar 500 USDT masuk ke insurance fund."],"mistakes":["Mengira insurance fund akan mengganti kerugian pribadi Anda saat dilikuidasi.","Menyamakan insurance fund dengan jaminan simpanan atau proof of reserves.","Mengabaikan ukuran insurance fund saat trading altcoin kecil dengan leverage tinggi."],"faq":[{"q":"Apakah insurance fund melindungi saldo saya jika exchange bangkrut?","a":"Tidak. Insurance fund hanya menutup kerugian dari likuidasi di pasar futures. Perlindungan simpanan pengguna adalah hal lain dan berbeda di tiap exchange dan negara."},{"q":"Dari mana dana insurance fund berasal?","a":"Umumnya dari sisa margin posisi yang berhasil dilikuidasi di harga lebih baik dari harga kebangkrutan, dan kadang dari kontribusi exchange sendiri."}],"title":"Apa itu insurance fund di futures kripto? Arti dan fungsinya","description":"Pahami insurance fund di exchange futures kripto: cara dana ini menutup kerugian likuidasi, hubungannya dengan ADL, dan batasannya.","related":[["auto-deleveraging","Auto-deleveraging (ADL)","Auto-deleveraging adalah mekanisme darurat exchange futures yang otomatis menutup sebagian posisi trader yang sedang untung untuk menutup kerugian dari posisi bangkrut, ketika insurance fund tidak cukup."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["proof-of-reserves","Proof of reserves (bukti cadangan)","Proof of reserves adalah cara exchange membuktikan bahwa aset yang dipegangnya setidaknya sama dengan saldo yang dimiliki pengguna, biasanya dengan menunjukkan alamat dompet dan bukti Merkle tree."],["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Likuidasi: siapa yang menekan tombol tutup paksa?"},"coin":null,"tool":"/liquidations","cta":false},"block-confirmations":{"slug":"block-confirmations","cat":"wallets-security","en":"Block confirmations","contentLocale":"id","term":"Konfirmasi blok (block confirmations)","aka":["block confirmations","konfirmasi","konfirmasi jaringan"],"short":"Konfirmasi blok adalah jumlah blok yang sudah ditambahkan sejak transaksi Anda masuk ke blockchain, dan semakin banyak konfirmasi berarti semakin kecil kemungkinan transaksi itu dibatalkan.","body":["Saat transaksi masuk ke sebuah blok, ia mendapat 1 konfirmasi. Setiap blok baru di atasnya menambah satu konfirmasi lagi. Karena mengubah transaksi lama berarti harus menulis ulang semua blok sesudahnya, transaksi dengan banyak konfirmasi praktis permanen.",["Exchange menetapkan jumlah konfirmasi minimum sebelum deposit dikreditkan atau bisa ditarik. Angkanya berbeda per jaringan dan per exchange. ",["Bitcoin","bitcoin"]," dengan blok sekitar 10 menit bisa butuh beberapa konfirmasi, sedangkan jaringan dengan blok cepat sering meminta puluhan konfirmasi yang tetap selesai dalam hitungan menit."],["Inilah alasan deposit Anda bisa terlihat berhasil di ",["block explorer","block-explorer"]," tetapi belum masuk saldo exchange. Lihat halaman deposit atau detail koin di exchange untuk mengetahui syarat konfirmasi yang berlaku."]],"example":["Misalnya exchange mensyaratkan 2 konfirmasi untuk deposit BTC dan rata-rata waktu blok Bitcoin sekitar 10 menit. Anda mengirim 0,05 BTC pukul 10.00. Transaksi masuk blok pada 10.08, menjadi 1 konfirmasi. Blok berikutnya muncul 10.19, sehingga transaksi mencapai 2 konfirmasi dan 0,05 BTC dikreditkan sekitar pukul 10.20. Jika biaya yang Anda bayar rendah dan ",["mempool","mempool"]," ramai, menunggu blok pertama saja bisa jauh lebih lama."],"mistakes":["Mengirim ulang dana karena deposit belum masuk padahal konfirmasi masih berjalan.","Mengira jumlah konfirmasi yang sama berlaku di semua exchange dan semua koin.","Menganggap 0 konfirmasi sudah aman untuk menerima pembayaran bernilai besar."],"faq":[{"q":"Berapa konfirmasi yang dibutuhkan untuk deposit?","a":"Tergantung jaringan dan exchange. Angka pastinya tercantum di halaman deposit atau informasi koin di exchange Anda."},{"q":"Mengapa transaksi saya 0 konfirmasi lama sekali?","a":"Biasanya karena biaya transaksi terlalu rendah dibanding transaksi lain di mempool. Transaksi akan menunggu sampai penambang atau validator memasukkannya ke blok."}],"title":"Apa itu konfirmasi blok? Arti block confirmations","description":"Arti konfirmasi blok, mengapa exchange meminta jumlah konfirmasi tertentu, dan kenapa deposit kripto bisa terasa lambat.","related":[["transaction-hash","Transaction hash (TxID)","Transaction hash atau TxID adalah kode unik untuk setiap transaksi di blockchain, yang bisa Anda pakai untuk melacak status transfer di block explorer."],["block-explorer","Block explorer","Block explorer adalah situs atau aplikasi untuk mencari dan melihat data blockchain secara publik, seperti status transaksi, saldo alamat, isi blok, dan jumlah konfirmasi."],["mempool","Mempool","Mempool adalah ruang tunggu tempat transaksi yang sudah disiarkan tetapi belum masuk blok disimpan sementara oleh node, sebelum dipilih oleh penambang atau validator."],["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Tertulis terkirim, tapi belum sampai. Harus cek ke mana?"},"coin":null,"tool":null,"cta":false},"impermanent-loss":{"slug":"impermanent-loss","cat":"defi","en":"Impermanent loss","contentLocale":"id","term":"Impermanent loss (kerugian tidak permanen)","aka":["IL","kerugian tidak permanen","divergence loss"],"short":"Impermanent loss adalah selisih nilai antara menyetor token ke liquidity pool dan sekadar menyimpannya di dompet, yang muncul ketika harga kedua token di pool bergerak berbeda.","body":[["Di pool ",["AMM","amm"],", ",["arbitrase","arbitrage"]," terus menyeimbangkan isi pool mengikuti ",["harga pasar","last-price"],". Jika ",["ETH","ethereum"]," naik, pool secara otomatis menjual sebagian ETH dan menambah ",["USDC","usdc"],". Hasilnya, Anda memegang lebih sedikit token yang naik dan lebih banyak token yang turun dibanding jika hanya menyimpannya."],["Disebut tidak permanen karena jika harga kembali ke titik awal, selisihnya hilang. Namun jika Anda menarik ",["likuiditas","liquidity"]," saat harga sudah jauh bergeser, kerugian itu menjadi nyata. Besarnya hanya bergantung pada perubahan rasio harga, bukan arahnya: naik 4 kali lipat atau turun menjadi seperempat sama-sama menghasilkan impermanent loss sekitar 20% pada pool 50/50."],"Fee swap dan insentif bisa menutupi impermanent loss, tetapi tidak selalu. Pasangan stabil seperti USDC/USDT umumnya memiliki impermanent loss kecil, sedangkan pasangan volatil dan concentrated liquidity bisa memperbesarnya."],"example":"Anda menyetor 1 ETH dan 2.000 USDC ke pool saat harga ETH 2.000 USDC, total 4.000 USDC. Harga ETH kemudian naik menjadi 8.000 USDC, empat kali lipat. Setelah arbitrase, porsi Anda di pool menjadi sekitar 0,5 ETH dan 4.000 USDC, bernilai 8.000 USDC. Jika Anda hanya menyimpan 1 ETH dan 2.000 USDC, nilainya 10.000 USDC. Selisih 2.000 USDC atau 20% itulah impermanent loss, sebelum memperhitungkan fee yang Anda terima.","mistakes":["Menganggap posisi untung hanya karena nilainya dalam dolar naik, tanpa membandingkannya dengan sekadar menyimpan token.","Mengira impermanent loss hanya terjadi saat harga turun.","Memilih pasangan sangat volatil hanya karena APR yang ditampilkan tinggi."],"faq":[{"q":"Apakah impermanent loss bisa dihindari?","a":"Tidak sepenuhnya di pool AMM dua aset volatil. Risiko bisa dikurangi dengan memilih pasangan berkorelasi tinggi seperti stablecoin, atau memastikan fee yang diperoleh cukup besar."},{"q":"Kapan impermanent loss menjadi permanen?","a":"Saat Anda menarik likuiditas ketika harga sudah berbeda dari harga saat menyetor. Selama masih di pool, nilainya bisa berubah lagi mengikuti harga."}],"title":"Apa itu impermanent loss? Arti dan cara menghitungnya","description":"Pelajari arti impermanent loss di liquidity pool, contoh perhitungannya, dan cara menilai apakah fee cukup untuk menutupinya.","related":[["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi."],["amm","AMM (automated market maker)","AMM adalah mekanisme di DEX yang menentukan harga secara otomatis berdasarkan rumus dan isi liquidity pool, sehingga Anda bisa swap tanpa menunggu pembeli atau penjual lain."],["yield-farming","Yield farming","Yield farming adalah strategi menempatkan aset kripto di berbagai protokol DeFi, seperti liquidity pool atau lending, untuk mendapatkan fee, bunga, dan token insentif."],["apr-vs-apy","APR vs APY","APR adalah tingkat imbal hasil tahunan tanpa bunga berbunga, sedangkan APY sudah memperhitungkan efek bunga berbunga (compounding), sehingga APY selalu sama atau lebih tinggi dari APR dengan tingkat dasar yang sama."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"liquid-staking":{"slug":"liquid-staking","cat":"defi","en":"Liquid staking","contentLocale":"id","term":"Liquid staking","aka":["staking likuid","LST","liquid staking token"],"short":"Liquid staking adalah cara staking di mana Anda menerima token pengganti, seperti stETH dari Lido, yang mewakili koin yang di-stake beserta reward-nya dan tetap bisa diperdagangkan atau dipakai di DeFi.","body":[[["Staking","staking"]," biasa mengunci koin, sehingga Anda tidak bisa memakainya sampai masa unbonding selesai. Protokol liquid staking menerima koin Anda, mendelegasikannya ke ",["validator","validator"],", lalu menerbitkan liquid staking token (LST). Contohnya stETH dan wstETH dari Lido, rETH dari Rocket Pool, atau jitoSOL di Solana."],["Token ini mengakumulasi reward dengan dua cara. Ada yang saldonya bertambah setiap hari (rebasing), seperti stETH. Ada yang jumlahnya tetap tetapi nilainya terhadap koin dasar terus naik, seperti wstETH dan rETH. LST bisa dijadikan jaminan pinjaman, disetor ke ",["liquidity pool","liquidity-pool"],", atau dipakai untuk ",["restaking","restaking"],"."],["Risikonya: bug ",["smart contract","smart-contract"],", kinerja validator, dan ",["depeg","depeg"],", yaitu LST diperdagangkan di bawah nilai koin dasarnya saat banyak orang ingin keluar bersamaan. Jika Anda menjual di pasar saat depeg, Anda menerima lebih sedikit dari nilai teoretis."]],"example":"Anda menyetor 5 ETH ke protokol liquid staking dan menerima sekitar 5 stETH. Dengan imbal hasil contoh 3% per tahun, setelah setahun saldo Anda menjadi sekitar 5,15 stETH. Suatu hari Anda butuh ETH cepat, tetapi di DEX 1 stETH sedang dihargai 0,99 ETH. Menjual 5,15 stETH menghasilkan sekitar 5,10 ETH, bukan 5,15 ETH. Alternatifnya, Anda mengajukan penarikan melalui antrean resmi protokol yang memerlukan waktu tunggu.","mistakes":["Menganggap 1 LST selalu bisa dijual tepat seharga 1 koin dasar.","Meminjam dengan jaminan LST memakai rasio tinggi tanpa memperhitungkan risiko depeg dan likuidasi.","Bingung membedakan token rebasing dan token yang nilainya naik, sehingga salah menghitung reward."],"faq":[{"q":"Apa beda staking biasa dan liquid staking?","a":"Staking biasa mengunci koin sampai masa unbonding selesai. Liquid staking memberi Anda token pengganti yang tetap bisa dipindahkan, diperdagangkan, atau dipakai di DeFi."},{"q":"Apakah stETH sama dengan ETH?","a":"Tidak sama. stETH adalah klaim atas ETH yang di-stake melalui Lido, biasanya bernilai mendekati 1 ETH, tetapi harga pasarnya bisa sedikit menyimpang."}],"title":"Apa itu liquid staking? Arti LST seperti stETH","description":"Pelajari arti liquid staking, cara kerja token seperti stETH dan rETH, serta risiko depeg dan smart contract yang perlu dipahami.","related":[["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama."],["restaking","Restaking","Restaking adalah memakai kembali ETH atau token liquid staking yang sudah di-stake untuk ikut mengamankan layanan lain, dengan imbalan reward tambahan sekaligus risiko slashing tambahan."],["wrapped-token","Wrapped token (token terbungkus)","Wrapped token adalah token yang mewakili aset lain dengan perbandingan 1:1, misalnya WBTC yang mewakili BTC di Ethereum, sehingga aset itu bisa dipakai di jaringan atau aplikasi yang tidak mendukungnya secara langsung."],["depeg","Depeg","Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS."]],"lesson":null,"coin":{"slug":"lido-dao","name":"Lido DAO","symbol":"LDO"},"tool":null,"cta":false},"restaking":{"slug":"restaking","cat":"defi","en":"Restaking","contentLocale":"id","term":"Restaking","aka":["restaking ETH","liquid restaking","LRT"],"short":"Restaking adalah memakai kembali ETH atau token liquid staking yang sudah di-stake untuk ikut mengamankan layanan lain, dengan imbalan reward tambahan sekaligus risiko slashing tambahan.","body":[["Konsep ini dipopulerkan oleh EigenLayer di ",["Ethereum","ethereum"],". ",["Validator","validator"]," atau pemegang ",["LST","liquid-staking"]," memberi izin agar stake mereka juga dipakai untuk mengamankan layanan lain, seperti oracle, bridge, atau jaringan data. Layanan ini sering disebut AVS (actively validated services). Sebagai imbalan, restaker mendapat reward tambahan dari layanan tersebut."],["Ada juga protokol liquid restaking yang menerbitkan token LRT, sehingga posisi restaking Anda tetap bisa dipindahkan atau dipakai di ",["DeFi","defi"],". Ini menambah satu lapisan lagi di atas liquid staking."],["Setiap lapisan menambah risiko. Selain risiko ",["staking","staking"]," biasa, restaking menambah aturan slashing dari layanan lain, risiko ",["smart contract","smart-contract"]," dari protokol restaking dan LRT, serta risiko depeg jika LRT dijual di bawah nilainya. Sebagian imbal hasil yang diiklankan juga berupa poin atau token yang nilainya belum pasti."]],"example":"Misalnya Anda memegang 10 stETH yang menghasilkan reward staking contoh 3% per tahun. Anda melakukan restaking 10 stETH tersebut ke beberapa AVS yang menjanjikan reward tambahan contoh 2% per tahun, sehingga total imbal hasil sekitar 5% atau 0,5 ETH setahun. Namun jika salah satu operator melakukan kesalahan dan terkena slashing 1%, Anda kehilangan 0,1 stETH, yang menghapus seperlima reward tahunan tersebut.","mistakes":["Hanya melihat reward tambahan tanpa membaca aturan slashing dari layanan yang diamankan.","Menghitung poin restaking seolah sudah setara uang.","Menumpuk restaking, LRT, dan pinjaman sekaligus tanpa memahami risiko setiap lapisan."],"faq":[{"q":"Apa beda staking dan restaking?","a":"Staking mengamankan satu blockchain. Restaking memakai stake yang sama untuk ikut mengamankan layanan tambahan, dengan reward dan risiko slashing tambahan."},{"q":"Apakah restaking cocok untuk pemula?","a":"Restaking menambah beberapa lapisan risiko di atas staking biasa. Pahami dulu staking dan liquid staking sebelum mencoba, dan mulai dengan jumlah yang siap Anda tanggung risikonya."}],"title":"Apa itu restaking? Arti restaking ETH dan risikonya","description":"Pelajari arti restaking, peran EigenLayer dan AVS, token LRT, serta risiko slashing tambahan yang ikut Anda tanggung.","related":[["liquid-staking","Liquid staking","Liquid staking adalah cara staking di mana Anda menerima token pengganti, seperti stETH dari Lido, yang mewakili koin yang di-stake beserta reward-nya dan tetap bisa diperdagangkan atau dipakai di DeFi."],["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama."],["validator","Validator","Validator adalah peserta jaringan proof of stake yang mengunci koin sebagai jaminan dan menjalankan software untuk mengusulkan serta mengesahkan blok baru."],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"defi-lending":{"slug":"defi-lending","cat":"defi","en":"DeFi lending","contentLocale":"id","term":"DeFi lending (pinjam-meminjam DeFi)","aka":["lending DeFi","pinjaman kripto DeFi","lending protocol"],"short":"DeFi lending adalah layanan pinjam-meminjam kripto lewat smart contract, di mana pemberi pinjaman mendapat bunga dan peminjam harus menyetor jaminan melebihi nilai pinjamannya.","body":[["Protokol seperti Aave, Compound, dan Morpho mengumpulkan dana dari pemberi pinjaman ke dalam pool. Peminjam menyetor jaminan, misalnya ",["ETH","ethereum"],", lalu meminjam aset lain seperti ",["USDC","usdc"],". Suku bunga berubah otomatis mengikuti tingkat pemakaian pool: semakin banyak yang dipinjam, semakin tinggi bunganya."],["Karena tidak ada pemeriksaan kredit, hampir semua pinjaman ",["DeFi","defi"]," bersifat overcollateralized. Setiap protokol menetapkan rasio pinjaman maksimum dan ambang ",["likuidasi","liquidation"]," untuk setiap aset. Harga jaminan dibaca dari oracle. Jika nilai jaminan turun sampai melewati ambang, likuidator boleh melunasi sebagian utang dan mengambil jaminan Anda dengan potongan harga sebagai bonus."],"Banyak protokol menampilkan health factor. Di atas 1 berarti posisi aman, di bawah 1 berarti bisa dilikuidasi. Parameter seperti rasio maksimum, ambang likuidasi, dan penalti berbeda di tiap protokol dan tiap aset, jadi periksa halaman pasar sebelum meminjam."],"example":"Misalnya Anda menyetor 4 ETH saat harga ETH 2.500 USDC, sehingga jaminan bernilai 10.000 USDC, lalu meminjam 6.000 USDC. Anggap ambang likuidasi untuk ETH 80%. Health factor = 10.000 × 80% ÷ 6.000 ≈ 1,33. Likuidasi terjadi saat nilai jaminan × 80% turun di bawah 6.000, yaitu saat jaminan bernilai di bawah 7.500 USDC, atau harga ETH di bawah 1.875 USDC. Menambah jaminan atau melunasi sebagian utang akan menaikkan health factor.","mistakes":["Meminjam mendekati batas maksimum sehingga penurunan harga kecil sudah memicu likuidasi.","Lupa bahwa bunga pinjaman terus bertambah dan perlahan menurunkan health factor.","Mengira likuidasi hanya mengambil sebagian kecil jaminan tanpa penalti."],"faq":[{"q":"Mengapa pinjaman DeFi harus memakai jaminan lebih besar?","a":"Karena protokol tidak mengenal identitas peminjam. Jaminan berlebih memastikan utang tetap bisa dilunasi dengan menjual jaminan jika harga turun."},{"q":"Apa itu health factor?","a":"Health factor adalah ukuran keamanan posisi pinjaman. Angka di bawah 1 berarti posisi dapat dilikuidasi oleh protokol."}],"title":"Apa itu DeFi lending? Cara kerja pinjaman kripto","description":"Pelajari cara kerja DeFi lending, jaminan berlebih, health factor, dan bagaimana likuidasi terjadi saat harga jaminan turun.","related":[["defi","DeFi (keuangan terdesentralisasi)","DeFi adalah layanan keuangan yang berjalan di atas smart contract di blockchain, seperti swap, pinjam-meminjam, dan staking, tanpa perantara seperti bank atau exchange terpusat."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["oracle","Oracle blockchain","Oracle blockchain adalah layanan yang membawa data dari luar blockchain, seperti harga aset, ke dalam smart contract agar kontrak bisa mengambil keputusan berdasarkan data tersebut."],["crypto-backed-stablecoin","Stablecoin berjaminan kripto (crypto-backed stablecoin)","Stablecoin berjaminan kripto adalah stablecoin yang dicetak dengan mengunci aset kripto seperti ETH sebagai jaminan dengan nilai lebih besar daripada stablecoin yang diterbitkan."],["flash-loan","Flash loan (pinjaman kilat)","Flash loan adalah pinjaman tanpa jaminan di DeFi yang harus dipinjam dan dikembalikan dalam satu transaksi yang sama; jika tidak dilunasi, seluruh transaksi dibatalkan otomatis."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cbdc":{"slug":"cbdc","cat":"stablecoins","en":"CBDC (central bank digital currency)","contentLocale":"id","term":"CBDC (mata uang digital bank sentral)","aka":["central bank digital currency","mata uang digital bank sentral","rupiah digital"],"short":"CBDC adalah bentuk digital dari mata uang resmi suatu negara yang diterbitkan dan dijamin langsung oleh bank sentral, misalnya rupiah digital yang sedang dikaji Bank Indonesia.","body":[["CBDC berbeda dengan ",["stablecoin","stablecoin"],". Stablecoin seperti ",["USDT","usdt"]," diterbitkan perusahaan swasta dan dijamin cadangan milik perusahaan itu. CBDC adalah kewajiban langsung bank sentral, sama seperti uang kertas, hanya bentuknya digital."],"Ada dua jenis utama. CBDC wholesale dipakai antarbank dan lembaga keuangan untuk penyelesaian transaksi besar. CBDC ritel bisa dipakai masyarakat sehari-hari. Di Indonesia, Bank Indonesia menjalankan Proyek Garuda untuk mengkaji rupiah digital, dimulai dari tahap wholesale. Tiongkok sudah menguji coba e-CNY secara luas.","CBDC tidak sama dengan kripto terdesentralisasi. Pasokan dan aturan dikendalikan bank sentral, transaksi bisa dipantau sesuai regulasi, dan tidak ada harga yang naik turun terhadap mata uang aslinya. Bagi trader kripto, CBDC lebih berperan sebagai jalur pembayaran dan bukan aset untuk spekulasi."],"example":"Misalkan suatu hari rupiah digital ritel tersedia. Anda memegang Rp1.000.000 dalam bentuk digital di dompet resmi. Nilainya selalu tepat Rp1.000.000, sama seperti uang tunai, karena 1 rupiah digital setara 1 rupiah. Bandingkan dengan 64 USDT yang Anda beli di kurs Rp15.600, sekitar Rp998.400. Jika kurs dolar naik ke Rp16.000, nilai USDT itu menjadi Rp1.024.000, sedangkan rupiah digital tetap Rp1.000.000. Jadi CBDC tidak terpengaruh kurs, sedangkan stablecoin dolar terpengaruh.","mistakes":["Menganggap CBDC sebagai koin kripto yang bisa naik harganya.","Menyamakan CBDC dengan stablecoin swasta seperti USDT atau USDC.","Percaya pada token yang mengaku sebagai rupiah digital resmi di luar kanal resmi bank sentral."],"faq":[{"q":"Apakah rupiah digital sudah bisa dipakai?","a":"Bank Indonesia masih mengembangkan rupiah digital lewat Proyek Garuda secara bertahap. Pantau pengumuman resmi Bank Indonesia untuk status terbaru dan waspadai token palsu yang mengatasnamakannya."},{"q":"Apa beda CBDC dengan stablecoin?","a":"CBDC diterbitkan bank sentral dan merupakan uang resmi negara. Stablecoin diterbitkan perusahaan swasta dan nilainya bergantung pada cadangan serta kepercayaan pada penerbitnya."}],"title":"Apa itu CBDC? Arti mata uang digital bank sentral","description":"Pahami arti CBDC, bedanya dengan stablecoin dan kripto, serta perkembangan rupiah digital di Indonesia.","related":[["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["fiat-on-ramp","Fiat on-ramp","Fiat on-ramp adalah layanan atau jalur untuk menukar uang biasa seperti rupiah menjadi aset kripto, misalnya lewat transfer bank, kartu, e-wallet, atau P2P di bursa."],["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."],["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Apakah USDT itu dolar? Mengapa sering muncul saat beli kripto?"},"coin":null,"tool":null,"cta":false},"node":{"slug":"node","cat":"onchain","en":"Node","contentLocale":"id","term":"Node","aka":["node blockchain","full node"],"short":"Node adalah komputer yang menjalankan perangkat lunak blockchain, menyimpan salinan data, memeriksa transaksi dan blok sesuai aturan, lalu meneruskannya ke node lain di jaringan.","body":[["Ada beberapa jenis node. Full node menyimpan dan memverifikasi seluruh riwayat aturan ",["blockchain","blockchain"]," secara mandiri. Light node hanya mengunduh sebagian data dan bergantung pada full node. Archive node menyimpan seluruh status historis, sering dipakai oleh explorer dan penyedia data."],["Node tidak sama dengan penambang atau ",["validator","validator"],". Penambang di ",["proof of work","proof-of-work"]," dan validator di ",["proof of stake","proof-of-stake"]," memang menjalankan node, tetapi mereka juga bertugas membuat atau mengusulkan blok. Node biasa cukup memeriksa dan menolak transaksi yang melanggar aturan, misalnya pengeluaran ganda."],"Semakin banyak node yang tersebar, semakin sulit jaringan dikendalikan satu pihak. Saat Anda memakai dompet seperti MetaMask, dompet itu biasanya terhubung ke node milik penyedia RPC. Menjalankan node sendiri memberi privasi dan kemandirian lebih, tetapi butuh penyimpanan, internet stabil, dan perawatan."],"example":["Misalkan Anda ingin menjalankan full node ",["Bitcoin","bitcoin"]," di rumah. Anda menyiapkan SSD 2 TB karena data blockchain sudah berukuran ratusan gigabyte dan terus bertambah. Sinkronisasi awal bisa memakan waktu satu sampai beberapa hari tergantung kecepatan perangkat dan internet. Jika node Anda aktif 24 jam dan berbagi data dengan sekitar 10 node lain, pemakaian kuota bisa ratusan gigabyte per bulan. Imbalannya, dompet Anda bisa memeriksa transaksi lewat node sendiri tanpa mempercayai server pihak ketiga."],"mistakes":["Mengira menjalankan node biasa akan menghasilkan imbalan seperti menambang atau staking.","Memakai RPC publik yang tidak jelas asalnya untuk dompet bernilai besar.","Menyamakan semua jenis node padahal kebutuhan full node, light node, dan archive node berbeda."],"faq":[{"q":"Apakah menjalankan node Bitcoin menghasilkan uang?","a":"Full node biasa tidak mendapat imbalan. Manfaatnya adalah verifikasi mandiri, privasi, dan ikut menjaga desentralisasi jaringan."},{"q":"Apa beda node dan validator?","a":"Semua validator menjalankan node, tetapi tidak semua node adalah validator. Validator mengunci aset sebagai stake untuk ikut mengusulkan dan mengesahkan blok di jaringan proof of stake."}],"title":"Apa itu node blockchain? Arti dan jenisnya","description":"Pelajari arti node di blockchain, beda full node, light node, dan validator, serta manfaat menjalankan node sendiri.","related":[["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."],["validator","Validator","Validator adalah peserta jaringan proof of stake yang mengunci koin sebagai jaminan dan menjalankan software untuk mengusulkan serta mengesahkan blok baru."],["mining","Mining (penambangan kripto)","Mining atau penambangan kripto adalah proses memakai daya komputasi untuk memvalidasi transaksi dan menambahkan blok baru pada blockchain proof of work, dengan imbalan koin baru dan biaya transaksi."],["mempool","Mempool","Mempool adalah ruang tunggu tempat transaksi yang sudah disiarkan tetapi belum masuk blok disimpan sementara oleh node, sebelum dipilih oleh penambang atau validator."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"aml":{"slug":"aml","cat":"regulation","en":"AML (anti-money laundering)","contentLocale":"id","term":"AML (anti pencucian uang)","aka":["Anti-Money Laundering","APU PPT","anti pencucian uang"],"short":"AML adalah kumpulan aturan dan prosedur untuk mencegah dana hasil kejahatan dicuci lewat sistem keuangan, termasuk lewat bursa dan transfer aset kripto.","body":[["Di Indonesia, istilah yang sering dipakai adalah APU PPT, yaitu Anti Pencucian Uang dan Pencegahan Pendanaan Terorisme. ",["Bursa kripto","centralized-exchange"]," menerapkannya lewat ",["KYC","kyc"],", pemantauan transaksi, penyaringan ",["alamat dompet","wallet-address"],", dan pelaporan transaksi mencurigakan kepada otoritas seperti PPATK."],"Dalam praktik, sistem AML bursa memeriksa pola transaksi. Contohnya setoran besar yang langsung ditarik, dana dari alamat yang terhubung dengan peretasan atau penipuan, atau transaksi yang dipecah-pecah agar tidak terdeteksi. Jika ada tanda bahaya, bursa bisa meminta penjelasan sumber dana atau menahan dana sementara.","Bagi pengguna biasa, AML terasa sebagai pertanyaan tambahan: dari mana dana berasal, untuk apa transaksi dilakukan. Jawab dengan jujur dan simpan bukti, misalnya slip gaji atau riwayat transaksi. Hindari menerima kripto dari pihak tak dikenal, karena dana itu bisa membuat akun Anda ditinjau."],"example":["Misalkan Anda menerima 3.000 ",["USDT","usdt"]," dari pembeli ",["P2P","p2p-trading"]," yang tidak dikenal di luar platform. Saat Anda menyetorkannya ke bursa, sistem penyaringan menemukan bahwa dana tersebut pernah melewati alamat yang ditandai terkait penipuan. Bursa lalu menahan 3.000 USDT itu dan meminta dokumen asal dana. Jika Anda bisa menunjukkan bukti percakapan dan transfer rupiah yang sah, peninjauan lebih mudah diselesaikan. Tanpa bukti, dana bisa tertahan lama. Inilah alasan transaksi P2P sebaiknya dilakukan lewat fitur resmi bursa dengan escrow."],"mistakes":["Memecah transfer besar menjadi banyak transaksi kecil, yang justru terlihat mencurigakan.","Menerima kripto dari orang tak dikenal tanpa tahu asal dananya.","Memberikan jawaban asal saat bursa meminta keterangan sumber dana."],"faq":[{"q":"Kenapa dana saya ditahan bursa karena AML?","a":"Biasanya karena sistem mendeteksi pola atau sumber dana yang berisiko, misalnya dari alamat yang ditandai. Hubungi dukungan resmi bursa dan siapkan bukti asal dana."},{"q":"Apa hubungan AML dan KYC?","a":"KYC adalah salah satu bagian dari program AML. KYC memastikan siapa nasabahnya, sedangkan AML juga mencakup pemantauan transaksi dan pelaporan ke otoritas."}],"title":"Apa itu AML di kripto? Arti anti pencucian uang","description":"Pelajari arti AML atau APU PPT di bursa kripto, kenapa dana bisa ditahan, dan cara menghindari masalah sumber dana.","related":[["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."],["travel-rule","Travel rule","Travel rule adalah aturan yang mewajibkan penyedia jasa aset kripto mengirim dan menerima data pengirim serta penerima bersama transfer kripto, mengikuti Rekomendasi 16 FATF."],["vasp","VASP (penyedia jasa aset virtual)","VASP adalah istilah FATF untuk perusahaan yang menyediakan jasa aset kripto bagi orang lain, seperti bursa, penyedia kustodi, dan layanan transfer, yang wajib mematuhi aturan AML dan KYC."],["p2p-trading","P2P trading (jual beli P2P)","P2P trading adalah jual beli kripto langsung antarpengguna di platform bursa, di mana pembayaran rupiah dilakukan lewat transfer bank atau e-wallet dan kripto penjual ditahan sistem escrow."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"Bagaimana cara kerja KYC dan kepada siapa identitas diberikan?"},"coin":null,"tool":null,"cta":false},"tokenized-gold":{"slug":"tokenized-gold","cat":"tokenized-assets","en":"Tokenized gold","contentLocale":"id","term":"Emas tokenisasi (tokenized gold)","aka":["tokenized gold","token emas","PAXG","XAUT"],"short":"Emas tokenisasi adalah token blockchain yang setiap unitnya didukung sejumlah emas fisik yang disimpan kustodian, misalnya PAXG dan XAUT yang masing-masing mewakili satu troy ounce emas.","body":[["PAX Gold (PAXG) diterbitkan oleh Paxos, sedangkan Tether Gold (XAUT) diterbitkan oleh Tether. Emas fisiknya disimpan di brankas, dan pemegang token bisa memperdagangkannya 24 jam di ",["bursa kripto","centralized-exchange"]," atau mentransfernya ke dompet. Harga token mengikuti harga emas internasional, bukan pergerakan kripto."],["Kelebihannya: bisa membeli pecahan kecil, tidak perlu menyimpan emas fisik, dan mudah dipindahkan. Penebusan ke emas fisik atau ke uang tunai biasanya dimungkinkan lewat penerbit dengan syarat ",["KYC","kyc"],", jumlah minimum, dan biaya tertentu."],["Risikonya: Anda bergantung pada penerbit dan kustodian untuk menjaga emas dan mengizinkan penebusan. Di bursa, harga token bisa sedikit berbeda dari harga emas spot karena ",["likuiditas","liquidity"],". Harga emas dalam rupiah juga dipengaruhi kurs dolar, berbeda dengan emas batangan yang Anda beli di toko lokal."]],"example":["Misalkan harga emas 2.400 dolar per troy ounce dan Anda membeli 0,05 PAXG senilai 120 ",["USDT","usdt"],". Satu troy ounce sekitar 31,1 gram, jadi Anda memegang klaim atas sekitar 1,56 gram emas. Jika harga emas naik 5% menjadi 2.520 dolar, nilai token Anda menjadi 126 USDT. Jika pada saat yang sama kurs rupiah melemah dari Rp15.500 ke Rp16.000 per dolar, nilai dalam rupiah naik dari Rp1.860.000 menjadi Rp2.016.000, karena terpengaruh harga emas dan kurs sekaligus."],"mistakes":["Mengira emas tokenisasi bisa ditebus fisik dalam jumlah berapa pun tanpa syarat.","Tidak memperhitungkan pengaruh kurs dolar terhadap nilai dalam rupiah.","Membeli token emas dari penerbit tidak dikenal tanpa bukti audit cadangan."],"faq":[{"q":"Apakah 1 PAXG sama dengan 1 gram emas?","a":"Tidak. 1 PAXG mewakili satu troy ounce emas, sekitar 31,1 gram. Hal yang sama berlaku untuk XAUT."},{"q":"Apa beda emas tokenisasi dan emas digital di aplikasi lokal?","a":"Emas tokenisasi berada di blockchain dan bisa dipindahkan ke dompet kripto. Emas digital di aplikasi lokal biasanya tercatat di sistem perusahaan dan diatur aturan setempat."}],"title":"Apa itu emas tokenisasi? PAXG, XAUT, dan cara kerjanya","description":"Pelajari emas tokenisasi seperti PAXG dan XAUT, cara token didukung emas fisik, penebusan, dan pengaruh kurs rupiah.","related":[["real-world-assets","Real World Assets (RWA, aset dunia nyata)","Real World Assets (RWA) adalah aset dari dunia keuangan nyata, seperti surat utang negara, kredit, properti, emas, atau saham, yang kepemilikannya direpresentasikan sebagai token di blockchain."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["custodial-wallet","Dompet kustodian (custodial wallet)","Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri."],["tokenized-stocks","Saham tokenisasi (tokenized stocks)","Saham tokenisasi adalah token di blockchain yang mewakili atau mengikuti harga saham nyata, seperti saham perusahaan AS, sehingga bisa diperdagangkan di platform kripto, sering 24 jam."]],"lesson":null,"coin":{"slug":"pax-gold","name":"PAX Gold","symbol":"PAXG"},"tool":"/topics/tokenized-assets","cta":false}});
